import { useId } from "react";
import { cn } from "./cn";
import { LOCKUP, LOCKUP_MONO, LOGO_CONCEPT, SYMBOL, SYMBOL_MONO, type LogoArt } from "./logo-data.generated";

/**
 * Callwright logo (docs/brand/logo-options.html). The art is generated by
 * scripts/brand/apply_concept.py into logo-data.generated.ts; colours come from the --logo-* tokens
 * in index.css, so it follows the theme. `compact` shows the symbol only (collapsed rail),
 * `onConsole` forces the dark palette on always-dark surfaces, `mono` draws in currentColor.
 * The animation runs on hover of the logo or of a link around it, never idle, and is off under
 * reduced motion.
 */
export function Logo({
  compact,
  className,
  onConsole,
  mono,
  height = 32,
  animated = true,
}: {
  compact?: boolean;
  className?: string;
  onConsole?: boolean;
  mono?: boolean;
  height?: number;
  animated?: boolean;
}) {
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const art: LogoArt = compact ? (mono ? SYMBOL_MONO : SYMBOL) : mono ? LOCKUP_MONO : LOCKUP;
  return (
    <span
      className={cn(
        "logo inline-flex shrink-0 items-center",
        `logo-${LOGO_CONCEPT}`,
        onConsole && "logo-on-dark",
        animated && "logo-anim",
        className,
      )}
    >
      <svg
        viewBox={`0 0 ${art.w} ${art.h}`}
        height={height}
        width={(height * art.w) / art.h}
        role="img"
        aria-label="Callwright"
        dangerouslySetInnerHTML={{ __html: art.markup.replaceAll("__UID__", uid) }}
      />
    </span>
  );
}
